// Turns new Drive files and webhook calls into ONE item { files: [{ url, name }] },
// so each Actor below starts once per execution, however many invoices arrived.
// Drive files must be readable by link (see Setup). Only XML and PDF files are passed on.
const files = [];
const add = (url, name) => {
  url = String(url || '').trim();
  if (url && !files.some(f => f.url === url)) files.push({ url, name: name || url.split('/').pop().split('?')[0] });
};
for (const item of $input.all()) {
  const j = item.json;
  if (j.body && (j.body.url || j.body.urls)) {   // Webhook: POST { "url": "https://...", "name": "optional" } or { "urls": [...] }
    if (j.body.url) add(j.body.url, j.body.name);
    for (const u of j.body.urls || []) add(u);
    continue;
  }
  if (!j.id) continue;                                    // not a Drive file
  const isXml = /xml/i.test(j.mimeType || '') || /\.xml$/i.test(j.name || '');
  const isPdf = j.mimeType === 'application/pdf' || /\.pdf$/i.test(j.name || '');
  if (!isXml && !isPdf) continue;                         // folders, images, Google Docs ...
  add(`https://drive.google.com/uc?export=download&id=${j.id}`, j.name);
}
return files.length ? [{ json: { files } }] : [];

// Collects the values to check from all parsed invoices: IBANs, seller VAT IDs and seller names.
// Duplicates are removed, so ten invoices from the same supplier cost one VAT check and one BaFin screening.
const norm = s => String(s || '').replace(/^IBAN/i, '').replace(/[\s.\-]/g, '').toUpperCase();
const uniq = a => [...new Set(a.filter(Boolean))];
const rows = $input.all().map(i => i.json).filter(r => r.status === 'ok');
return [{ json: {
  ibans: uniq(rows.map(r => norm(r.iban))),
  vatNumbers: uniq(rows.map(r => norm(r.seller && r.seller.vatId))),
  names: uniq(rows.map(r => String((r.seller && r.seller.name) || '').trim())),
} }];

// Builds the traffic light per invoice: red = do not pay before a human has checked,
// yellow = something could not be verified, green = all automatic checks passed.
// This is a technical pre-check, not tax or legal advice.
const norm = s => String(s || '').replace(/^IBAN/i, '').replace(/[\s.\-]/g, '').toUpperCase();
const simple = s => String(s || '').toLowerCase().replace(/\b(gmbh|ag|kg|ug|se|mbh|co|ltd|limited|sarl|sas|bv|nv|srl|spa)\b|[^a-z0-9äöüß]/g, '');
const ibanRows = $('Check IBANs').all().map(i => i.json).filter(r => r.input);
const vatRows = $('Check VAT IDs').all().map(i => i.json).filter(r => r.input);
const bafinRows = $('Screen BaFin warnings').all().map(i => i.json).filter(r => r.query);
const files = $('Collect invoice files').first().json.files;

return $('Parse e-invoices').all().map(({ json: p }) => {
  const red = [], yellow = [];
  const s = p.seller || {};
  const file = (files.find(f => f.url === p.fileUrl) || {}).name || p.fileUrl;

  // 1. Structured e-invoice?
  if (p.status !== 'ok') yellow.push(`Not readable as XRechnung/ZUGFeRD (${String(p.error || p.status).slice(0, 120)}) - check manually`);
  if (p.validationWarningCount > 0) yellow.push(`${p.validationWarningCount} plausibility warning(s): ${p.validationWarnings[0]}`);

  // 2. IBAN
  let bank = '';
  if (p.status === 'ok') {
    const i = ibanRows.find(r => norm(r.input) === norm(p.iban));
    if (!p.iban) yellow.push('No IBAN on the invoice (direct debit, card or other payment means?)');
    else if (!i) yellow.push('IBAN check not available - run again');
    else if (!i.valid) red.push(`IBAN ${i.iban || p.iban} is invalid: ${i.error || 'checksum/format error'}`);
    else {
      bank = [i.bankName, i.bic].filter(Boolean).join(' / ');
      if (i.error) yellow.push(`IBAN checksum OK, but: ${i.error}`);
      if (s.country && i.countryCode && i.countryCode !== s.country) yellow.push(`IBAN country ${i.countryCode} differs from seller country ${s.country}`);
      if (i.sepa === false) yellow.push(`IBAN country ${i.countryCode} is outside SEPA`);
    }
  }

  // 3. Seller VAT ID (VIES)
  let vies = '';
  if (p.status === 'ok') {
    const vat = norm(s.vatId);
    const v = vatRows.find(r => norm(r.fullVatNumber || r.input) === vat || norm(r.input) === vat);
    vies = v ? v.status : (vat ? 'not checked' : 'missing');
    if (!vat) yellow.push(s.taxNumber ? 'No VAT ID on the invoice, only a tax number (Steuernummer) - VIES check not possible' : 'No seller VAT ID on the invoice');
    else if (!v) yellow.push('VAT ID check not available - run again');
    else if (v.status === 'invalid') red.push(`VAT ID ${v.fullVatNumber} is not valid according to VIES`);
    else if (v.status === 'format_error') red.push(`VAT ID ${s.vatId} has an invalid format`);
    else if (v.status !== 'valid') yellow.push(`VIES could not answer for ${v.fullVatNumber || vat} (${v.status}) - check again later`);
    else if (v.name && simple(v.name) && !simple(v.name).includes(simple(s.name)) && !simple(s.name).includes(simple(v.name)))
      yellow.push(`VIES name "${v.name}" differs from invoice name "${s.name}"`);
  }

  // 4. BaFin warnings (screened by seller name)
  let bafin = '';
  if (p.status === 'ok' && s.name) {
    const b = bafinRows.find(r => r.query === String(s.name).trim());
    if (!b) yellow.push('BaFin screening not available - run again');
    else if (b.matched) { bafin = `${b.title} (${b.url})`; red.push(`Seller matches a BaFin warning (score ${b.matchScore}): ${b.title} ${b.url}`); }
    else if (b.matchScore >= 70) yellow.push(`Seller name is similar to a BaFin warning (score ${b.matchScore}) - check bafin.de`);
  }

  const light = red.length ? 'red' : yellow.length ? 'yellow' : 'green';
  return { json: {
    checked_at: $now.toFormat('yyyy-MM-dd HH:mm'),
    light,
    reasons: [...red, ...yellow].join('; ') || 'all automatic checks passed',
    file,
    invoice_number: p.invoiceNumber || '',
    issue_date: p.issueDate || '',
    due_date: p.dueDate || '',
    seller: s.name || '',
    seller_vat_id: s.vatId || '',
    vies_status: vies,
    iban: p.iban || '',
    bank,
    bafin_match: bafin,
    amount_due: p.payableAmount ?? '',
    currency: p.currency || '',
    format: p.format || '',
    source_url: p.fileUrl,
  } };
});

// One alert for all red invoices of this run. No red invoice = nothing is sent.
const red = $input.all().map(i => i.json).filter(r => r.light === 'red');
if (!red.length) return [];
const line = r => `${r.seller || r.file} | invoice ${r.invoice_number} | ${r.amount_due} ${r.currency}\n   ${r.reasons}`;
const text = `:red_circle: ${red.length} incoming invoice(s) need a manual check before payment\n\n` + red.map(line).join('\n\n');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
return [{ json: {
  text,
  subject: `${red.length} incoming invoice(s) flagged red`,
  html: '<p>These invoices need a manual check before payment:</p><ul>' +
    red.map(r => `<li><b>${esc(r.seller || r.file)}</b>, invoice ${esc(r.invoice_number)}, ${esc(r.amount_due)} ${esc(r.currency)}<br>${esc(r.reasons)}</li>`).join('') + '</ul>',
} }];
